import pytest
from candidate import fib


class TestFibonacci:
    def test_fib_zero_returns_zero(self):
        assert fib(0) == 0

    def test_fib_one_returns_one(self):
        assert fib(1) == 1

    def test_fib_two_returns_one(self):
        assert fib(2) == 1

    def test_fib_three_returns_two(self):
        assert fib(3) == 2

    def test_fib_four_returns_three(self):
        assert fib(4) == 3

    def test_fib_five_returns_five(self):
        assert fib(5) == 5

    def test_fib_eight_returns_twenty_one(self):
        assert fib(8) == 21

    def test_fib_ten_returns_fifty_five(self):
        assert fib(10) == 55

    def test_fib_twelve_returns_one_hundred_fourty_four(self):
        assert fib(12) == 144

    def test_fib_negative_number_raises_error(self):
        with pytest.raises(Exception):
            fib(-1)

    def test_fib_none_raises_error(self):
        with pytest.raises(Exception):
            fib(None)

    def test_fib_string_raises_error(self):
        with pytest.raises(Exception):
            fib("10")

    def test_fib_float_raises_or_returns_value(self):
        with pytest.raises(Exception):
            fib(1.5)

    def test_fib_list_raises_error(self):
        with pytest.raises(Exception):
            fib([1, 2, 3])

    def test_fib_dict_raises_error(self):
        with pytest.raises(Exception):
            fib({})

    def test_fib_bool_true_returns_one(self):
        assert fib(True) == 1

    def test_fib_bool_false_returns_zero(self):
        assert fib(False) == 0

    def test_fib_returns_int_type(self):
        result = fib(5)
        assert isinstance(result, int)

    def test_fib_sequence_consistency(self):
        for i in range(2, 11):
            assert fib(i) == fib(i - 1) + fib(i - 2)

    def test_fib_zero_boundary(self):
        assert fib(0) == 0

    def test_fib_one_boundary(self):
        assert fib(1) == 1

    def test_fib_large_number_completes(self):
        assert fib(20) == 6765
